/**
 * is responsible for normalizing the Typescript type before the type is exposed back to the user.
 *
 * @internal
 */
declare type Normalized<T extends ProcedureDef> = T extends any ? {
    key: T["key"];
    result: OmitRecursively<T["result"], "$id" | "$type">;
    input: T["input"];
} : never;

// Referenced local context (not public exports):
declare type OmitRecursively<T extends any, K extends PropertyKey> = Omit<{
    [P in keyof T]: OmitDistributive<T[P], K>;
}, K>;

declare type OmitDistributive<T, K extends PropertyKey> = T extends any ? T extends object ? Id<OmitRecursively<T, K>> : T : never;

declare type Id<T> = {} & {
    [P in keyof T]: T[P];
};
